// Excretory Products and their Elimination — generated by Claude (no source PDF).
// Covers modes of nitrogenous waste excretion, the human excretory system,
// nephron structure, urine formation (filtration/reabsorption/secretion),
// counter-current mechanism, regulation (ADH/RAAS/ANF), micturition, and
// disorders of the excretory system.

export const EXCRETORY_PRODUCTS_ELIMINATION = [
  // ---- MCQ ----
  { id: 'ep-1', type: 'mcq', question: 'The process of removing metabolic nitrogenous waste products from the body is called:', options: ['Digestion', 'Excretion', 'Respiration', 'Circulation'], correctIndex: 1, explanation: 'Excretion is the removal of nitrogenous and other metabolic wastes from the body.', difficulty: 'easy' },
  { id: 'ep-2', type: 'mcq', question: 'Organisms that excrete nitrogenous waste primarily as ammonia are called:', options: ['Ureotelic', 'Uricotelic', 'Ammonotelic', 'Aminotelic'], correctIndex: 2, explanation: 'Ammonotelic organisms (like many aquatic animals) excrete ammonia directly, as it readily dissolves in surrounding water.', difficulty: 'medium' },
  { id: 'ep-3', type: 'mcq', question: 'Organisms that excrete nitrogenous waste primarily as urea are called:', options: ['Ammonotelic', 'Ureotelic', 'Uricotelic', 'Non-nitrogenous excretors'], correctIndex: 1, explanation: 'Ureotelic organisms, including humans, convert toxic ammonia into less toxic urea for excretion.', difficulty: 'medium' },
  { id: 'ep-4', type: 'mcq', question: 'Organisms that excrete nitrogenous waste primarily as uric acid are called:', options: ['Ammonotelic', 'Ureotelic', 'Uricotelic', 'Osmoconformers'], correctIndex: 2, explanation: 'Uricotelic organisms (like birds and reptiles) excrete relatively insoluble uric acid, conserving water.', difficulty: 'medium' },
  { id: 'ep-5', type: 'mcq', question: 'The conversion of toxic ammonia into urea in humans occurs mainly in the:', options: ['Kidney', 'Liver', 'Lungs', 'Skin'], correctIndex: 1, explanation: 'The liver converts ammonia into urea via the ornithine (urea) cycle.', difficulty: 'medium' },
  { id: 'ep-6', type: 'mcq', question: "The primary excretory organs in humans, responsible for forming urine, are the:", options: ['Lungs', 'Kidneys', 'Skin', 'Liver'], correctIndex: 1, explanation: 'The kidneys are the principal organs responsible for excretion and urine formation in humans.', difficulty: 'easy' },
  { id: 'ep-7', type: 'mcq', question: 'The functional and structural unit of the kidney is the:', options: ['Nephron', 'Neuron', 'Alveolus', 'Sarcomere'], correctIndex: 0, explanation: 'The nephron is the basic structural and functional unit responsible for urine formation.', difficulty: 'easy' },
  { id: 'ep-8', type: 'mcq', question: 'Each nephron begins with a cup-shaped structure called the:', options: ['Loop of Henle', "Bowman's capsule", 'Collecting duct', 'Renal pelvis'], correctIndex: 1, explanation: "Bowman's capsule is the cup-shaped structure enclosing the glomerulus at the start of the nephron.", difficulty: 'medium' },
  { id: 'ep-9', type: 'mcq', question: "The network of blood capillaries enclosed within Bowman's capsule, where filtration begins, is called the:", options: ['Glomerulus', 'Vasa recta', 'Loop of Henle', 'Peritubular capillary network'], correctIndex: 0, explanation: 'The glomerulus is the capillary tuft where blood filtration initiates urine formation.', difficulty: 'medium' },
  { id: 'ep-10', type: 'mcq', question: "Together, Bowman's capsule and the glomerulus are collectively referred to as the:", options: ['Loop of Henle', 'Malpighian body (renal corpuscle)', 'Collecting duct', 'Renal pelvis'], correctIndex: 1, explanation: "The Malpighian body (or renal corpuscle) is the combined structure of Bowman's capsule and the glomerulus.", difficulty: 'medium' },
  { id: 'ep-11', type: 'mcq', question: "Following the renal corpuscle, filtrate passes next into the:", options: ['Loop of Henle directly', 'Proximal Convoluted Tubule (PCT)', 'Collecting duct directly', 'Renal artery'], correctIndex: 1, explanation: 'The PCT is the next segment after the renal corpuscle, involved in extensive reabsorption.', difficulty: 'medium' },
  { id: 'ep-12', type: 'mcq', question: 'The hairpin-shaped segment of the nephron connecting the PCT and DCT, essential for concentrating urine, is the:', options: ['Loop of Henle', 'Collecting duct', 'Renal pelvis', "Bowman's capsule"], correctIndex: 0, explanation: 'The Loop of Henle, with its descending and ascending limbs, plays a key role in the counter-current mechanism.', difficulty: 'medium' },
  { id: 'ep-13', type: 'mcq', question: "Nephrons whose loops of Henle extend deep into the medulla, playing a major role in concentrating urine, are called:", options: ['Cortical nephrons', 'Juxtamedullary nephrons', 'Peripheral nephrons', 'Renal nephrons only'], correctIndex: 1, explanation: 'Juxtamedullary nephrons, with their long loops extending into the medulla, are crucial for the concentration mechanism.', difficulty: 'medium' },
  { id: 'ep-14', type: 'mcq', question: 'The first step of urine formation, involving the passage of blood plasma components from the glomerulus into the Bowman\'s capsule, is called:', options: ['Tubular reabsorption', 'Tubular secretion', 'Glomerular filtration', 'Micturition'], correctIndex: 2, explanation: 'Glomerular filtration is the initial, non-selective filtration step forming the glomerular filtrate.', difficulty: 'easy' },
  { id: 'ep-15', type: 'mcq', question: 'The amount of glomerular filtrate formed by both kidneys per minute is called the:', options: ['Tubular Maximum (Tm)', 'Glomerular Filtration Rate (GFR)', 'Renal Plasma Flow', 'Osmotic filtration rate'], correctIndex: 1, explanation: 'GFR is the volume of filtrate formed per minute by both kidneys combined, normally about 125 mL/minute.', difficulty: 'medium' },
  { id: 'ep-16', type: 'mcq', question: 'The process by which useful substances (like glucose, amino acids, and much of the water) are absorbed back from the filtrate into the blood is called:', options: ['Glomerular filtration', 'Tubular reabsorption', 'Tubular secretion', 'Micturition'], correctIndex: 1, explanation: 'Tubular reabsorption recovers useful filtered substances back into the peritubular capillary blood.', difficulty: 'easy' },
  { id: 'ep-17', type: 'mcq', question: 'Most of the reabsorption of glucose, amino acids, and a large fraction of water and salts occurs in the:', options: ['Loop of Henle', 'Proximal Convoluted Tubule (PCT)', 'Distal Convoluted Tubule (DCT)', 'Collecting duct only'], correctIndex: 1, explanation: 'The PCT is the site of most reabsorption, reclaiming nearly all glucose/amino acids and much of the filtered water/salts.', difficulty: 'medium' },
  { id: 'ep-18', type: 'mcq', question: 'The process by which certain substances (like H+, K+, and some drugs) are actively transported from blood into the tubular filtrate is called:', options: ['Glomerular filtration', 'Tubular reabsorption', 'Tubular secretion', 'Osmoregulation'], correctIndex: 2, explanation: 'Tubular secretion adds selected substances from blood into the filtrate, aiding in maintaining ionic/acid-base balance.', difficulty: 'medium' },
  { id: 'ep-19', type: 'mcq', question: 'The mechanism by which the loop of Henle and vasa recta work together to help concentrate urine is called the:', options: ['Osmoconformity mechanism', 'Counter-current mechanism', 'Direct filtration mechanism', 'Active transport mechanism only'], correctIndex: 1, explanation: 'The counter-current mechanism, involving opposite-flow arrangements in the loop of Henle and vasa recta, enables concentrated urine formation.', difficulty: 'medium' },
  { id: 'ep-20', type: 'mcq', question: "The descending limb of the loop of Henle is generally:", options: ['Impermeable to water but permeable to salts', 'Permeable to water but relatively impermeable to salts/electrolytes', 'Impermeable to both water and salts', 'Highly permeable to both water and salts equally'], correctIndex: 1, explanation: 'The descending limb allows water to leave (into the hyperosmotic medullary interstitium) but is largely impermeable to salts.', difficulty: 'medium' },
  { id: 'ep-21', type: 'mcq', question: 'The ascending limb of the loop of Henle is generally:', options: ['Permeable to water but not salts', 'Impermeable to water but permits active/passive transport of electrolytes', 'Permeable to both water and salts equally', 'Completely impermeable to everything'], correctIndex: 1, explanation: 'The ascending limb is impermeable to water but actively/passively transports salts out, contributing to the medullary gradient.', difficulty: 'medium' },
  { id: 'ep-22', type: 'mcq', question: "The blood vessels running parallel to the loop of Henle, playing a role in maintaining the medullary concentration gradient, are called the:", options: ['Renal artery and vein', 'Vasa recta', 'Afferent and efferent arterioles', 'Peritubular capillaries only'], correctIndex: 1, explanation: 'The vasa recta are specialised capillaries that run alongside the loop of Henle, helping preserve the osmotic gradient.', difficulty: 'medium' },
  { id: 'ep-23', type: 'mcq', question: 'The hormone that increases the permeability of the distal tubule and collecting duct to water, promoting water reabsorption, is:', options: ['Aldosterone', 'Antidiuretic Hormone (ADH/vasopressin)', 'Renin', 'Atrial Natriuretic Factor (ANF)'], correctIndex: 1, explanation: 'ADH increases water permeability of the DCT/collecting duct, concentrating urine and conserving body water.', difficulty: 'medium' },
  { id: 'ep-24', type: 'mcq', question: 'ADH is released from the:', options: ['Kidney directly', 'Posterior pituitary gland', 'Adrenal cortex', 'Liver'], correctIndex: 1, explanation: 'ADH (vasopressin), synthesised in the hypothalamus, is released from the posterior pituitary.', difficulty: 'medium' },
  { id: 'ep-25', type: 'mcq', question: 'A fall in blood pressure/volume or a decrease in glomerular filtration rate can activate a hormonal cascade beginning with the release of:', options: ['ADH directly', 'Renin, from the juxtaglomerular apparatus of the kidney', 'Insulin', 'Thyroxine'], correctIndex: 1, explanation: 'Renin release from the juxtaglomerular apparatus initiates the renin-angiotensin-aldosterone system (RAAS).', difficulty: 'medium' },
  { id: 'ep-26', type: 'mcq', question: "Renin converts angiotensinogen (produced in the liver) into:", options: ['Angiotensin II directly', 'Angiotensin I', 'Aldosterone', 'ADH'], correctIndex: 1, explanation: 'Renin cleaves angiotensinogen into angiotensin I, which is later converted to angiotensin II.', difficulty: 'medium' },
  { id: 'ep-27', type: 'mcq', question: 'Angiotensin II stimulates the adrenal cortex to release which hormone, promoting sodium and water reabsorption?', options: ['Aldosterone', 'Cortisol', 'Adrenaline', 'ADH'], correctIndex: 0, explanation: 'Aldosterone, released in response to angiotensin II, promotes Na+ (and water) reabsorption, raising blood volume/pressure.', difficulty: 'medium' },
  { id: 'ep-28', type: 'mcq', question: 'Atrial Natriuretic Factor (ANF), released from the heart, generally acts to:', options: ['Increase blood pressure and promote water retention', 'Decrease blood pressure by promoting vasodilation and reducing sodium/water reabsorption', 'Have no effect on renal function', 'Only affect the respiratory system'], correctIndex: 1, explanation: 'ANF acts as a check on RAAS, lowering blood pressure by dilating vessels and reducing Na+/water reabsorption.', difficulty: 'medium' },
  { id: 'ep-29', type: 'mcq', question: 'Urine produced in the kidney passes to the urinary bladder through the:', options: ['Urethra', 'Ureter', 'Renal artery', 'Renal vein'], correctIndex: 1, explanation: 'Ureters carry urine from each kidney down to the urinary bladder.', difficulty: 'easy' },
  { id: 'ep-30', type: 'mcq', question: 'Urine is expelled from the urinary bladder to outside the body through the:', options: ['Ureter', 'Urethra', 'Renal pelvis', 'Vas deferens'], correctIndex: 1, explanation: 'The urethra carries urine from the bladder out of the body.', difficulty: 'easy' },
  { id: 'ep-31', type: 'mcq', question: 'The process of voiding urine from the urinary bladder is called:', options: ['Filtration', 'Micturition', 'Reabsorption', 'Excretion generally'], correctIndex: 1, explanation: 'Micturition is the specific term for the act of urinating.', difficulty: 'medium' },
  { id: 'ep-32', type: 'mcq', question: 'The stretch receptors that signal a filled bladder, initiating the micturition reflex, are located in the:', options: ['Kidney', 'Wall of the urinary bladder', 'Ureter only', 'Loop of Henle'], correctIndex: 1, explanation: 'Stretch receptors in the bladder wall detect filling and signal the need to urinate.', difficulty: 'medium' },
  { id: 'ep-33', type: 'mcq', question: 'The outer region of the kidney, containing the renal corpuscles and convoluted tubules, is called the:', options: ['Medulla', 'Cortex', 'Pelvis', 'Hilum'], correctIndex: 1, explanation: 'The renal cortex is the outer region housing the renal corpuscles and most of the convoluted tubules.', difficulty: 'medium' },
  { id: 'ep-34', type: 'mcq', question: 'The inner region of the kidney, containing the pyramids and loops of Henle, is called the:', options: ['Cortex', 'Medulla', 'Hilum', 'Capsule only'], correctIndex: 1, explanation: 'The renal medulla contains the pyramidal structures and loops of Henle involved in concentrating urine.', difficulty: 'medium' },
  { id: 'ep-35', type: 'mcq', question: 'Urine collected from the collecting ducts drains into a funnel-shaped space called the:', options: ['Renal pelvis', 'Bowman\'s capsule', 'Glomerulus', 'Cortex'], correctIndex: 0, explanation: 'The renal pelvis collects urine before it passes into the ureter.', difficulty: 'medium' },
  { id: 'ep-36', type: 'mcq', question: 'Accumulation of urea and other nitrogenous wastes in the blood, often due to kidney failure, is called:', options: ['Diabetes insipidus', 'Uraemia', 'Glycosuria', 'Ketonuria'], correctIndex: 1, explanation: 'Uraemia is the abnormal accumulation of urea and related wastes in the blood.', difficulty: 'medium' },
  { id: 'ep-37', type: 'mcq', question: 'In cases of severe kidney failure, a technique that uses an artificial membrane to filter blood outside the body is called:', options: ['Micturition', 'Haemodialysis', 'Glomerular filtration (natural)', 'Angioplasty'], correctIndex: 1, explanation: 'Haemodialysis mimics kidney function using an artificial membrane to remove wastes from the blood.', difficulty: 'medium' },
  { id: 'ep-38', type: 'mcq', question: 'Small, hard, crystalline masses that can form within the kidney due to precipitation of substances like calcium oxalate are called:', options: ['Gallstones', 'Kidney stones (renal calculi)', 'Polyps', 'Cysts'], correctIndex: 1, explanation: 'Kidney stones (renal calculi) form when substances crystallise abnormally within the renal system.', difficulty: 'medium' },
  { id: 'ep-39', type: 'mcq', question: "Glomerulonephritis refers to:", options: ['Inflammation of the glomeruli of the kidney', 'A disorder of the liver only', 'A disorder involving excess glucose in urine', 'A disorder of the urinary bladder muscle'], correctIndex: 0, explanation: 'Glomerulonephritis is inflammation specifically affecting the glomeruli, impairing filtration.', difficulty: 'medium' },
  { id: 'ep-40', type: 'mcq', question: 'The presence of glucose in urine, often associated with diabetes mellitus, is called:', options: ['Uraemia', 'Glycosuria', 'Haematuria', 'Proteinuria'], correctIndex: 1, explanation: 'Glycosuria refers to glucose appearing in the urine, typically when blood glucose exceeds the renal reabsorption threshold.', difficulty: 'medium' },
  { id: 'ep-41', type: 'mcq', question: 'Which of the following is generally almost completely reabsorbed in a healthy kidney, appearing negligibly in normal urine?', options: ['Urea', 'Glucose', 'Uric acid', 'Creatinine'], correctIndex: 1, explanation: 'In a healthy kidney, essentially all filtered glucose is reabsorbed and does not normally appear in urine.', difficulty: 'medium' },
  { id: 'ep-42', type: 'mcq', question: 'Which of the following substances is NOT significantly reabsorbed and largely remains in the filtrate to be excreted?', options: ['Glucose', 'Amino acids', 'Urea (a large fraction remains)', 'Sodium (extensively reabsorbed)'], correctIndex: 2, explanation: 'While some urea is reabsorbed, a substantial fraction remains in the filtrate and is excreted, unlike glucose and amino acids.', difficulty: 'medium' },
  { id: 'ep-43', type: 'mcq', question: 'The regulation of body fluid osmolarity, ionic composition, and volume by the kidney is collectively termed:', options: ['Digestion', 'Osmoregulation', 'Respiration', 'Neurotransmission'], correctIndex: 1, explanation: 'Osmoregulation refers to maintaining the proper balance of water and solutes in body fluids.', difficulty: 'medium' },
  { id: 'ep-44', type: 'mcq', question: 'Besides the kidneys, which other organs/structures contribute to excretion of certain wastes in humans?', options: ['Lungs (CO2), skin (sweat), and liver (bile pigments)', 'Only the stomach', 'Only the pancreas', 'Only the spleen'], correctIndex: 0, explanation: 'The lungs, skin, and liver also play auxiliary roles in eliminating specific waste products.', difficulty: 'medium' },
  { id: 'ep-45', type: 'mcq', question: 'Sweat glands in human skin, besides thermoregulation, also help eliminate small amounts of:', options: ['Glucose only', 'Urea and lactic acid, among other substances', 'Bile pigments only', 'Digestive enzymes'], correctIndex: 1, explanation: 'Sweat contains small amounts of urea, lactic acid, and other minor waste substances.', difficulty: 'medium' },
  { id: 'ep-46', type: 'mcq', question: 'Bile pigments, derived from the breakdown of haemoglobin, are eliminated from the body mainly via:', options: ['Urine only', 'Faeces, via bile secreted by the liver', 'Sweat only', 'Exhaled air'], correctIndex: 1, explanation: 'Bile pigments (like bilirubin) are excreted through bile into the intestine and eventually leave via faeces.', difficulty: 'medium' },
  { id: 'ep-47', type: 'mcq', question: 'Which of the following would most directly result from damage to the glomerulus, impairing its filtration barrier?', options: ['Complete absence of urine formation only', 'Leakage of large proteins/blood cells into the filtrate (proteinuria/haematuria)', 'Increased reabsorption of glucose', 'No effect on urine composition at all'], correctIndex: 1, explanation: 'A damaged glomerular filtration barrier can allow proteins and blood cells to leak into the filtrate, causing proteinuria/haematuria.', difficulty: 'medium' },
  { id: 'ep-48', type: 'mcq', question: 'The juxtaglomerular apparatus (JGA), a specialised structure within the nephron involved in regulating GFR and blood pressure, is located near the:', options: ['Junction of the afferent arteriole and the distal convoluted tubule', 'Renal pelvis only', 'Bladder wall', 'Ureter'], correctIndex: 0, explanation: 'The JGA sits at the point where the afferent arteriole contacts the DCT, sensing and regulating filtration/blood pressure.', difficulty: 'hard' },
  { id: 'ep-49', type: 'mcq', question: 'Which of the following best describes why uricotelism is advantageous for birds and reptiles?', options: ['Uric acid requires large amounts of water to excrete', 'Uric acid is relatively insoluble and can be excreted as a semi-solid paste, conserving water', 'Uric acid is more toxic than ammonia, requiring less processing', 'It has no adaptive advantage at all'], correctIndex: 1, explanation: "Excreting insoluble uric acid as a paste conserves water, which is especially advantageous for egg-laying/land-dwelling animals.", difficulty: 'medium' },
  { id: 'ep-50', type: 'mcq', question: 'Which of the following best summarises the overall role of the human excretory system?', options: ['To produce digestive enzymes only', 'To remove metabolic wastes and help regulate body fluid volume, composition, and osmolarity', 'To generate ATP for cellular processes', 'To transmit nerve impulses'], correctIndex: 1, explanation: "The excretory system's core role is waste removal combined with regulating the body's internal fluid environment.", difficulty: 'medium' },

  // ---- Assertion-Reason ----
  { id: 'ep-ar-1', type: 'assertion-reason', question: 'Assertion (A): Humans are ureotelic organisms.\nReason (R): Humans convert toxic ammonia into less toxic urea before excretion.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This conversion to less toxic urea is exactly why humans are classified as ureotelic.', difficulty: 'medium' },
  { id: 'ep-ar-2', type: 'assertion-reason', question: 'Assertion (A): Birds and reptiles are uricotelic.\nReason (R): Excreting nitrogenous waste as uric acid, a relatively insoluble compound, helps conserve water.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Water conservation via low-solubility uric acid excretion is exactly why birds/reptiles evolved uricotelism.', difficulty: 'medium' },
  { id: 'ep-ar-3', type: 'assertion-reason', question: "Assertion (A): The nephron is the functional unit of the kidney.\nReason (R): Each nephron independently carries out filtration, reabsorption, and secretion to form urine.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Carrying out the complete urine-forming process is exactly why each nephron is considered a functional unit.', difficulty: 'medium' },
  { id: 'ep-ar-4', type: 'assertion-reason', question: "Assertion (A): The proximal convoluted tubule (PCT) reabsorbs almost all of the filtered glucose and amino acids.\nReason (R): The PCT has a highly folded (brush border) surface that increases surface area for reabsorption.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This increased surface area is exactly what enables the PCT to reabsorb such large amounts of filtered substances.', difficulty: 'medium' },
  { id: 'ep-ar-5', type: 'assertion-reason', question: 'Assertion (A): The descending limb of the loop of Henle is impermeable to water.\nReason (R): The ascending limb of the loop of Henle is impermeable to water but transports salts out into the interstitium.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The descending limb is actually PERMEABLE to water (A is false, since it claims impermeability); R correctly describes the properties of the ascending limb instead.', difficulty: 'medium' },
  { id: 'ep-ar-6', type: 'assertion-reason', question: "Assertion (A): The counter-current mechanism helps the kidney produce concentrated urine.\nReason (R): It relies on the opposite-direction flow of filtrate in the loop of Henle and blood in the vasa recta.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This opposite-flow arrangement is exactly what enables the counter-current mechanism to concentrate urine.', difficulty: 'medium' },
  { id: 'ep-ar-7', type: 'assertion-reason', question: 'Assertion (A): ADH decreases the permeability of the collecting duct to water.\nReason (R): ADH release leads to the production of dilute, high-volume urine.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 3, explanation: 'ADH actually INCREASES (not decreases) water permeability, leading to concentrated (not dilute) urine — both statements as given are false.', difficulty: 'medium' },
  { id: 'ep-ar-8', type: 'assertion-reason', question: 'Assertion (A): A fall in blood pressure can trigger renin release from the juxtaglomerular apparatus.\nReason (R): Renin converts angiotensinogen into angiotensin I, eventually leading to aldosterone release and increased Na+/water reabsorption.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This exact RAAS cascade, triggered by renin, is what restores blood pressure/volume after a drop.', difficulty: 'medium' },
  { id: 'ep-ar-9', type: 'assertion-reason', question: 'Assertion (A): Atrial Natriuretic Factor (ANF) increases blood pressure.\nReason (R): ANF promotes vasodilation and reduces sodium/water reabsorption in the kidney.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'ANF actually DECREASES (not increases) blood pressure (A is false); R correctly explains the actual vasodilatory, natriuretic mechanism.', difficulty: 'medium' },
  { id: 'ep-ar-10', type: 'assertion-reason', question: 'Assertion (A): Urine passes from the kidney to the urinary bladder through the urethra.\nReason (R): The ureter connects the kidney to the urinary bladder.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Urine actually travels via the URETER (not the urethra) to the bladder (A is false); R correctly identifies the ureter\'s role.', difficulty: 'medium' },
  { id: 'ep-ar-11', type: 'assertion-reason', question: 'Assertion (A): Micturition is initiated by stretch receptors in the bladder wall.\nReason (R): These receptors detect bladder filling and send signals that trigger the urge to urinate.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Detecting bladder distension and signalling the urge to void is exactly how these stretch receptors initiate micturition.', difficulty: 'medium' },
  { id: 'ep-ar-12', type: 'assertion-reason', question: 'Assertion (A): Uraemia refers to excess glucose accumulation in the blood.\nReason (R): Uraemia specifically refers to accumulation of urea and related nitrogenous wastes in the blood, often due to kidney failure.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Uraemia is about UREA (not glucose) accumulation (A is false); R correctly defines the real condition.', difficulty: 'medium' },
  { id: 'ep-ar-13', type: 'assertion-reason', question: 'Assertion (A): Haemodialysis is used to treat patients with severe kidney failure.\nReason (R): Haemodialysis uses an artificial membrane to filter wastes from the blood, mimicking normal kidney function.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This artificial filtration mimicking kidney function is exactly why haemodialysis helps kidney failure patients.', difficulty: 'medium' },
  { id: 'ep-ar-14', type: 'assertion-reason', question: 'Assertion (A): Glycosuria always indicates permanent, irreversible kidney damage.\nReason (R): Glycosuria can occur when blood glucose levels exceed the renal threshold for glucose reabsorption, as in diabetes mellitus.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Glycosuria does NOT necessarily indicate permanent kidney damage (A is false) — it can simply reflect exceeded reabsorption capacity, as R correctly explains.', difficulty: 'medium' },
  { id: 'ep-ar-15', type: 'assertion-reason', question: 'Assertion (A): The kidney cortex contains the renal corpuscles.\nReason (R): The renal medulla contains the loops of Henle and collecting ducts.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 1, explanation: 'Both statements are true and describe complementary kidney zones, but R does not directly explain WHY the cortex specifically holds renal corpuscles — they are simply parallel facts about kidney anatomy.', difficulty: 'medium' },
  { id: 'ep-ar-16', type: 'assertion-reason', question: 'Assertion (A): Juxtamedullary nephrons play a major role in producing concentrated urine.\nReason (R): Their long loops of Henle extend deep into the medulla, contributing significantly to the medullary osmotic gradient.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Deep medullary loop extension is exactly why juxtamedullary nephrons are so important for urine concentration.', difficulty: 'medium' },
  { id: 'ep-ar-17', type: 'assertion-reason', question: 'Assertion (A): Bile pigments are excreted through urine.\nReason (R): Bile pigments are eliminated mainly via bile into the intestine and then out with faeces.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Bile pigments are eliminated mainly through FAECES (not urine) via bile (A is false); R correctly describes the real elimination pathway.', difficulty: 'medium' },
  { id: 'ep-ar-18', type: 'assertion-reason', question: 'Assertion (A): The lungs contribute to excretion by removing carbon dioxide.\nReason (R): CO2 is a metabolic waste product generated during cellular respiration.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "CO2 being a respiratory waste product is exactly why the lungs' removal of it counts as an excretory function.", difficulty: 'medium' },
  { id: 'ep-ar-19', type: 'assertion-reason', question: 'Assertion (A): Kidney stones can form due to the precipitation of substances like calcium oxalate within the renal system.\nReason (R): Kidney stones are always harmless and never require any medical treatment.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 2, explanation: 'A is true (stones do form via precipitation), but R is false — kidney stones can cause significant pain/complications and often require treatment.', difficulty: 'medium' },
  { id: 'ep-ar-20', type: 'assertion-reason', question: 'Assertion (A): Glomerulonephritis involves inflammation of the glomeruli, impairing normal filtration.\nReason (R): Impaired glomerular filtration can lead to abnormal leakage of proteins or blood cells into urine.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Impaired filtration due to glomerular inflammation directly explains why abnormal substances can leak into the urine.', difficulty: 'medium' },

  // ---- Statement-based ----
  { id: 'ep-st-1', type: 'statement', question: 'Statement I: Humans are ureotelic, excreting urea as the main nitrogenous waste.\nStatement II: Birds are ureotelic as well.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — birds are uricotelic, not ureotelic.', difficulty: 'medium' },
  { id: 'ep-st-2', type: 'statement', question: "Statement I: The nephron begins with Bowman's capsule enclosing the glomerulus.\nStatement II: This combined structure is called the Malpighian body (renal corpuscle).", options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the initial structure of the nephron.', difficulty: 'easy' },
  { id: 'ep-st-3', type: 'statement', question: 'Statement I: Glomerular filtration is a highly selective process, filtering only specific molecules.\nStatement II: Glomerular filtration is largely non-selective, filtering most small plasma components except large proteins and cells.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — filtration is largely NON-selective (based on size), not highly selective; Statement II correctly describes this.', difficulty: 'medium' },
  { id: 'ep-st-4', type: 'statement', question: 'Statement I: Most glucose and amino acid reabsorption occurs in the PCT.\nStatement II: The DCT is the main site of glucose reabsorption.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — the PCT (not DCT) is the main glucose reabsorption site.', difficulty: 'medium' },
  { id: 'ep-st-5', type: 'statement', question: 'Statement I: The descending limb of the loop of Henle is permeable to water.\nStatement II: The ascending limb of the loop of Henle is impermeable to water.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the differential water permeability of the two limbs.', difficulty: 'medium' },
  { id: 'ep-st-6', type: 'statement', question: 'Statement I: ADH decreases water reabsorption in the collecting duct.\nStatement II: ADH release results in more concentrated urine.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — ADH actually INCREASES water reabsorption; Statement II correctly describes the resulting concentrated urine.', difficulty: 'medium' },
  { id: 'ep-st-7', type: 'statement', question: 'Statement I: Renin is released from the juxtaglomerular apparatus in response to low blood pressure.\nStatement II: Renin directly converts angiotensin I into angiotensin II.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — renin converts angiotensinogen to angiotensin I; a separate enzyme (ACE) converts angiotensin I to angiotensin II.', difficulty: 'hard' },
  { id: 'ep-st-8', type: 'statement', question: 'Statement I: Aldosterone promotes sodium and water reabsorption.\nStatement II: ANF promotes sodium and water reabsorption as well.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — ANF actually REDUCES (not promotes) sodium/water reabsorption.', difficulty: 'medium' },
  { id: 'ep-st-9', type: 'statement', question: 'Statement I: Ureters carry urine from the kidney to the bladder.\nStatement II: The urethra carries urine from the bladder to outside the body.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe these urinary tract structures.', difficulty: 'easy' },
  { id: 'ep-st-10', type: 'statement', question: 'Statement I: Micturition is a completely voluntary process with no involuntary component.\nStatement II: Micturition involves both involuntary reflex components and voluntary control.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — micturition involves both reflex and voluntary elements, not purely voluntary control; Statement II correctly describes this.', difficulty: 'medium' },
  { id: 'ep-st-11', type: 'statement', question: 'Statement I: The renal cortex is the outer region of the kidney.\nStatement II: The renal medulla is the inner region, containing pyramidal structures.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe basic kidney anatomy.', difficulty: 'easy' },
  { id: 'ep-st-12', type: 'statement', question: 'Statement I: Uraemia refers to excess urea accumulation in the blood.\nStatement II: Uraemia often results from kidney failure.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe uraemia and its common cause.', difficulty: 'medium' },
  { id: 'ep-st-13', type: 'statement', question: 'Statement I: Haemodialysis uses the patient\'s own kidney tissue for filtration.\nStatement II: Haemodialysis uses an artificial membrane to filter blood outside the body.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — haemodialysis uses an ARTIFICIAL membrane, not the patient\'s own kidney tissue; Statement II correctly describes the actual process.', difficulty: 'medium' },
  { id: 'ep-st-14', type: 'statement', question: 'Statement I: Kidney stones can form from precipitation of substances like calcium oxalate.\nStatement II: Kidney stones are also called renal calculi.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe kidney stones and their alternate name.', difficulty: 'easy' },
  { id: 'ep-st-15', type: 'statement', question: 'Statement I: Glycosuria refers to the presence of blood cells in urine.\nStatement II: Glycosuria refers to the presence of glucose in urine.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — that describes haematuria, not glycosuria; Statement II correctly defines glycosuria.', difficulty: 'medium' },
  { id: 'ep-st-16', type: 'statement', question: "Statement I: The lungs contribute to excretion by removing CO2.\nStatement II: The skin contributes to excretion via sweat, which contains small amounts of urea.", options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe auxiliary excretory roles of the lungs and skin.', difficulty: 'medium' },
  { id: 'ep-st-17', type: 'statement', question: 'Statement I: Bile pigments are eliminated mainly through urine.\nStatement II: Bile pigments are eliminated mainly through faeces.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — bile pigments leave mainly via faeces, not urine; Statement II correctly identifies the primary elimination route.', difficulty: 'medium' },
  { id: 'ep-st-18', type: 'statement', question: 'Statement I: The vasa recta run parallel to the loop of Henle.\nStatement II: The vasa recta help maintain the medullary osmotic gradient.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the vasa recta and their functional role.', difficulty: 'medium' },
  { id: 'ep-st-19', type: 'statement', question: 'Statement I: Juxtamedullary nephrons have short loops of Henle confined to the cortex.\nStatement II: Cortical nephrons have short loops of Henle, mostly confined to the cortex.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — juxtamedullary nephrons actually have LONG loops extending deep into the medulla; Statement II correctly describes cortical nephrons.', difficulty: 'medium' },
  { id: 'ep-st-20', type: 'statement', question: 'Statement I: Tubular secretion adds substances from blood into the tubular filtrate.\nStatement II: Tubular secretion helps maintain ionic and acid-base balance.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe tubular secretion and its physiological importance.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'ep-hm-1', type: 'statement', question: 'How many of the following are correct examples of excretion type — organism pairs?\nHumans — ureotelic, Birds — uricotelic, Aquatic animals (many) — ammonotelic, Fish (many) — uricotelic', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three pairs are correctly matched; most fish are actually ammonotelic (or ureotelic), not uricotelic.', difficulty: 'medium' },
  { id: 'ep-hm-2', type: 'statement', question: 'How many of the following are parts of a nephron?\nBowman\'s capsule, Glomerulus, Loop of Henle, Alveolus', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: "Bowman's capsule, glomerulus, and loop of Henle are nephron parts; an alveolus is a respiratory structure, unrelated to the nephron.", difficulty: 'medium' },
  { id: 'ep-hm-3', type: 'statement', question: 'How many of the following are steps involved in urine formation?\nGlomerular filtration, Tubular reabsorption, Tubular secretion, Bile secretion', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Filtration, reabsorption, and secretion are the three genuine steps of urine formation; bile secretion is a liver/digestive function, unrelated to urine formation.', difficulty: 'medium' },
  { id: 'ep-hm-4', type: 'statement', question: 'How many of the following hormones are involved in regulating kidney function/blood pressure?\nADH, Aldosterone, Renin, Insulin', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'ADH, aldosterone, and renin are directly involved in kidney/blood pressure regulation; insulin primarily regulates blood glucose, not kidney function directly.', difficulty: 'medium' },
  { id: 'ep-hm-5', type: 'statement', question: 'How many of the following are true regarding ADH?\nIt is released from the posterior pituitary, It increases water permeability of the collecting duct, It leads to concentrated urine formation, It is released from the kidney directly', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; ADH is released from the posterior pituitary (not directly from the kidney).', difficulty: 'medium' },
  { id: 'ep-hm-6', type: 'statement', question: 'How many of the following are components of the renin-angiotensin-aldosterone system (RAAS)?\nRenin, Angiotensinogen, Angiotensin II, Aldosterone', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are genuine components of the RAAS pathway.', difficulty: 'medium' },
  { id: 'ep-hm-7', type: 'statement', question: 'How many of the following are organs/structures contributing to excretion in humans?\nKidneys, Lungs, Skin, Liver', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four organs play some role in excreting metabolic wastes from the body.', difficulty: 'medium' },
  { id: 'ep-hm-8', type: 'statement', question: 'How many of the following are disorders related to the excretory system?\nUraemia, Kidney stones, Glomerulonephritis, Osteoporosis', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Uraemia, kidney stones, and glomerulonephritis are excretory system disorders; osteoporosis is a bone disorder, unrelated to excretion.', difficulty: 'medium' },
  { id: 'ep-hm-9', type: 'statement', question: 'How many of the following are true regarding the loop of Henle?\nThe descending limb is permeable to water, The ascending limb is impermeable to water, It is essential for the counter-current mechanism, It is found only in cortical nephrons, never in juxtamedullary nephrons', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; the loop of Henle is present in BOTH cortical and juxtamedullary nephrons (though longer in the latter).', difficulty: 'medium' },
  { id: 'ep-hm-10', type: 'statement', question: 'How many of the following correctly describe glomerular filtration?\nIt is the first step of urine formation, It is largely non-selective based on molecular size, Large proteins and blood cells are normally NOT filtered, It selectively filters only glucose molecules', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; filtration is size-based and non-selective, not specifically targeting only glucose.', difficulty: 'medium' },
];